import { useEffect, useState } from 'react';
import { io } from 'socket.io-client';

//const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5001';

function AlertFeed() {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    let mounted = true;
    const socket = io(API_URL);

    fetch(`${API_URL}/api/alerts`)
      .then((response) => response.json())
      .then((history) => {
        if (mounted && Array.isArray(history)) setAlerts(history);
      })
      .catch((error) => console.error('Unable to load alerts:', error));

    socket.on('alert', (alert) => {
      if (mounted) setAlerts((current) => [alert, ...current].slice(0, 50));
    });

    return () => {
      mounted = false;
      socket.disconnect();
    };
  }, []);

  return (
    <section className="panel alert-panel">
      <div className="panel-heading">
        <div>
          <p className="eyebrow">INCIDENT LOG</p>
          <h2>Recent alerts</h2>
        </div>
        <span className="metric-count">{alerts.length} EVENTS</span>
      </div>
      <div className="alert-list">
        {alerts.length === 0 && <p className="empty-state">No alerts received.</p>}
        {alerts.map((alert) => {
          const critical = alert.status?.toUpperCase().includes('CRITICAL');
          return (
            <article className={`alert-item ${critical ? 'critical' : ''}`} key={alert._id || `${alert.productID}-${alert.timestamp}`}>
              <div className="alert-indicator" />
              <div className="alert-copy">
                <div className="alert-title-row">
                  <strong>{alert.productID}</strong>
                  <time>{new Date(alert.timestamp).toLocaleTimeString()}</time>
                </div>
                <span>{alert.status}</span>
                <small>Torque {alert.torque} Nm / Wear {alert.toolWear} / RPM {alert.rotationalSpeed}</small>
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
}

export default AlertFeed;
